package app.servante.tools.signing

import app.servante.core.Availability
import app.servante.core.secrets.Secret
import kotlinx.coroutines.test.runTest
import java.nio.file.Path
import kotlin.test.Test
import kotlin.test.assertEquals
import kotlin.test.assertFalse
import kotlin.test.assertTrue
import kotlin.time.Instant

/**
 * Reads the keystores in `fixtures/fjord-notes/keystores/`, which were generated by `keytool` so the
 * certificates are real and the fingerprints are what a real tool would print.
 *
 * Behaviours:
 * - a JKS keystore is read: alias, algorithm, key size, validity, both fingerprints
 * - a PKCS12 keystore is read the same way, without the caller saying which format it is
 * - the SHA-1 and SHA-256 fingerprints match what keytool prints for the same file
 * - a keystore with several aliases returns all of them
 * - a wrong password is reported as unavailable, not as a crash, and the reason does not leak the password
 * - a file that is not a keystore is reported as unavailable
 * - a file that is not there is reported as unavailable
 * - the fingerprint is formatted as the colon-separated uppercase hex the consoles expect
 */
class KeystoreReaderTest {
    private val fixtures: Path = Path.of(
        requireNotNull(System.getProperty("servante.fixtures")) { "set by the test task" },
    )
    private val keystores = fixtures.resolve("fjord-notes/keystores")
    private val reader = KeystoreReader()

    private suspend fun read(file: String, password: String): Keystore {
        val result = reader.read(keystores.resolve(file).toString(), Secret(password))
        assertTrue(result is Availability.Available, "expected to read $file, got $result")
        return result.value
    }

    @Test
    fun `reads the debug keystore that keytool generated`() = runTest {
        val keystore = read("debug.keystore", "android")

        assertEquals("JKS", keystore.format)
        val entry = keystore.entries.single()
        assertEquals("androiddebugkey", entry.alias)
        assertEquals("RSA", entry.keyAlgorithm)
        assertEquals(2048, entry.keySizeBits)
        assertEquals("CN=Android Debug, O=Android, C=US", entry.subject)
        assertEquals(Instant.parse("2024-01-01T00:00:00Z"), entry.validFrom)
    }

    @Test
    fun `reads the release keystore`() = runTest {
        val entry = read("release.jks", "fjord-release-2024").entries.single()

        assertEquals("upload", entry.alias)
        assertEquals(4096, entry.keySizeBits)
        assertTrue("Fjord Notes Upload" in entry.subject)
    }

    @Test
    fun `reads a PKCS12 keystore without being told the format`() = runTest {
        val keystore = read("legacy.p12", "fjord-legacy")

        assertEquals("PKCS12", keystore.format)
        val entry = keystore.entries.single()
        assertEquals("legacy-key", entry.alias)
        assertEquals("EC", entry.keyAlgorithm)
        assertEquals(256, entry.keySizeBits)
    }

    @Test
    fun `the fingerprints match what keytool prints`() = runTest {
        val entry = read("debug.keystore", "android").entries.single()

        assertEquals(
            "2D:26:15:4E:8D:AA:F5:CD:F5:10:A8:7C:2A:80:C0:14:5A:21:F9:A1",
            entry.sha1.formatted,
        )
        assertEquals(
            "4C:26:B4:A1:2D:0D:BF:96:84:9E:E2:77:62:E0:B4:85:" +
                "F2:AE:E4:96:2D:E4:75:16:5F:54:48:0F:CE:61:57:11",
            entry.sha256.formatted,
        )
    }

    @Test
    fun `a fingerprint also renders in the plain form the Firebase console wants`() = runTest {
        val entry = read("debug.keystore", "android").entries.single()

        assertEquals("2d26154e8daaf5cdf510a87c2a80c0145a21f9a1", entry.sha1.plainLowercase)
    }

    @Test
    fun `a wrong password is unavailable and the reason does not contain the password`() = runTest {
        val result = reader.read(
            keystores.resolve("release.jks").toString(),
            Secret("definitely-not-the-password"),
        )

        assertTrue(result is Availability.Unavailable)
        assertFalse("definitely-not-the-password" in result.reason)
        assertTrue("release.jks" in result.reason)
    }

    @Test
    fun `a file that is not a keystore is unavailable`() = runTest {
        val result = reader.read(
            fixtures.resolve("fjord-notes/gradle.properties").toString(),
            Secret("whatever"),
        )

        assertTrue(result is Availability.Unavailable)
    }

    @Test
    fun `a file that is not there is unavailable`() = runTest {
        val result = reader.read(keystores.resolve("no-such.jks").toString(), Secret("x"))

        assertTrue(result is Availability.Unavailable)
        assertTrue("no-such.jks" in result.reason)
    }
}
